import subprocess

def test_calculate_checklist_progress_throws_type_error_on_nested_json():
    js_code = '''
    const rawData = { "0": { "items": [] } };
    const day = 1;
    function calculateChecklistProgress(rawDayChecklists, day) {
      if (!rawDayChecklists || typeof rawDayChecklists !== "object") {
        return { completed: 0, total: 0 };
      }
      const store = rawDayChecklists;
      let items = [];
      if (day === 1) {
        const d0 = store[0] || store["0"] || [];
        const d1 = store[1] || store["1"] || [];
        const map = new Map();
        [...d0, ...d1].forEach((item) => {
          if (item && item.id) map.set(item.id, item);
        });
        items = Array.from(map.values());
      } else {
        items = store[day] || store[String(day)] || [];
      }
      return { completed: 0, total: items.length };
    }
    try {
      calculateChecklistProgress(rawData, day);
      console.log("SUCCESS");
    } catch (err) {
      console.log(err.name + ": " + err.message);
    }
    '''
    res = subprocess.run(["node", "-e", js_code], capture_output=True, text=True, check=True)
    assert "TypeError" in res.stdout
